import kotlin.math.roundToInt
fun sum(vararg ns: Number): Double {
    var t = 0.0
    for (n in ns) t += n.toDouble()
    return t
}

fun <T : Comparable<T>> biggest(a: T, b: T): T = if (a > b) a else b

fun main() {
    // overflow
    println(Int.MAX_VALUE + 1)
    println(Int.MIN_VALUE - 1)
    println(Int.MAX_VALUE * 2)
    println(Long.MAX_VALUE + 1)
    println(Long.MIN_VALUE - 1)
    println(Long.MAX_VALUE * 3)
    println(-Int.MIN_VALUE)
    println(-Long.MIN_VALUE)
    println(Int.MIN_VALUE / -1)
    println(Int.MIN_VALUE % -1)
    println(Long.MIN_VALUE / -1)
    println(Int.MAX_VALUE.toLong() + 1)
    println(1 shl 33)
    println(1L shl 65)
    println(-8 shr 1)
    println(-8 ushr 28)
    println(-8L ushr 60)
    println(5 / 2)
    println(-5 / 2)
    println(-5 % 3)
    println(5.0 % -3)
    println(Int.MAX_VALUE.inc())
    // Double printing
    println(1.0)
    println(1.0E10)
    println(1.0E-5)
    println(123456789.0)
    println(1234567.0)
    println(12345678.9)
    println(0.001)
    println(0.0001)
    println(100.0 / 3)
    println(-0.0)
    println(0.0 == -0.0)
    println(0.0.equals(-0.0))
    println(Double.NaN)
    println(Double.NaN == Double.NaN)
