    println(1.0 / 0.0)
    println(-1.0 / 0.0)
    println(Double.MAX_VALUE)
    println(Double.MIN_VALUE)
    println(Double.POSITIVE_INFINITY)
    println(1e21)
    println(1e7)
    println(9999999.0)
    println(4.9E-324)
    println(2.5f)
    println(1.0f / 3)
    println(1e10f)
    println(0.1 + 0.2)
    println(3.0e-10)
    println(100.0)
    println(1.5e300 * 1e10)
    println((0.1f + 0.2f).toDouble())
    println(16777216f + 1f)
    println(Float.MAX_VALUE)
    println(Float.NaN)
    println(Long.MAX_VALUE.toDouble())
    println(Long.MAX_VALUE.toFloat())
    println(3.99.toInt())
    println(-3.99.toInt())
    println(1e20.toInt())
