    println(Double.NaN.toInt())
    println(2.5.toLong())
    // Number hierarchy
    val n: Number = 42
    println(n.toInt())
    println(n.toDouble())
    println(n.toLong())
    println(n.toByte())
    println(n.toShort())
    println(n.toFloat())
    val d: Number = 3.75
    println(d.toInt())
    println(d.toLong())
    println(d.toDouble())
    val ln: Number = 5000000000L
    println(ln.toInt())
    println(ln.toLong())
    println(sum(1, 2.5, 3L, 4.5f))
    val nums: List<Number> = listOf(1, 2L, 3.0, 4.0f, 5.toShort(), 6.toByte())
    println(nums)
    var acc = 0.0
    for (x in nums) acc += x.toDouble()
    println(acc)
    println(n is Int)
    println(n is Number)
    println(d is Double)
    // Comparable
    println(biggest(3, 7))
    println(biggest(3L, 7L))
    println(biggest(2.5, 1.5))
    println(biggest('a', 'z'))
    println(biggest("abc", "abd"))
