    println(1.5.compareTo(1.5))
    println('b'.compareTo('a'))
    println("b".compareTo("a"))
    println(true.compareTo(false))
    println(Double.NaN.compareTo(1.0))
    println(0.0.compareTo(-0.0))
    val cs: List<Comparable<Int>> = listOf(1, 2)
