    println(listOf("b", "a").sorted())
    println(listOf('b', 'a').sorted())
    println(listOf(3L, 1L).sorted())
    println(listOf(2.toByte(), 1.toByte()).sorted())
    // hashCode
    println(42.hashCode())
    println(-1.hashCode())
