    println(1.5f.hashCode())
    println(true.hashCode())
    println(false.hashCode())
    println('a'.hashCode())
    println("hello".hashCode())
    println(3.toByte().hashCode())
    println(3.toShort().hashCode())
    println(Long.MIN_VALUE.hashCode())
    val boxed: Any = 5000000000L
    println(boxed.hashCode())
    val boxedD: Any = 2.0
    println(boxedD.hashCode())
    println(1 == 1L.toInt())
    println(Int.MAX_VALUE.toString())
    println(Long.MIN_VALUE.toString())
    println(255.toString(16))
    println((-255).toString(2))
    println(Long.MAX_VALUE.toString(36))
    println("ff".toInt(16))
    println(Int.MAX_VALUE.coerceAtMost(5))
    println(7.coerceIn(1, 5))
    println(10.coerceAtLeast(20))
    println(-7 / 2)
