    println(Int.SIZE_BITS)
    println(Long.SIZE_BYTES)
    println(3.countOneBits())
    println(8.countTrailingZeroBits())
    println(1.countLeadingZeroBits())
    println(0x12345678.rotateLeft(8))
    println(3.7.roundToInt())
    println(3.2.toInt().toDouble())
